import React from "react";

export default function RefundPolicy() {
  return (
    <div style={{ padding: "20px" }}>
      <h1>Cancellation & Refund Policy</h1>
      <p>
        Donations made through StrayCare are voluntary and non-refundable as
        they go directly to NGOs helping animals in distress.
      </p>
      <p>
        If a payment issue occurs, please contact support@straycare.com.
      </p>
    </div>
  );
}
